public sealed class MappingDraft
{
    public string PlatformName{get;set;}="Douyin";public string ShopExternalId{get;set;}="";public string Product{get;set;}="";public string Variant{get;set;}="";public string SkuCode{get;set;}="";public decimal Multiplier{get;set;}=1;public bool Enabled{get;set;}=true;public int ExpectedVersion{get;set;}
}
public partial class MasterWindow:Window
{
    private OpeningPolicy _policy=new(false,0);
    private readonly LocalApiClient _api;private MasterSnapshot? _snapshot;private ShopProfile? _shop;private SkuProfile? _sku;private bool _busy;private string _preview="";
    public ObservableCollection<MappingDraft> MappingRows{get;}=[];
    public MasterWindow(LocalApiClient api){InitializeComponent();_api=api;ShopPlatform.ItemsSource=Enum.GetValues<Platform>();ShopPlatform.SelectedItem=Platform.Douyin;MappingsGrid.ItemsSource=MappingRows;}
    private async Task Run(Func<Task> action){if(_busy)return;_busy=true;Tabs.IsEnabled=false;try{await action();}catch(Exception e){StatusText.Text=e.Message+(_api.PendingCount>0?" 未确认请求已保留，请回订单中心用原请求重试。":"");}finally{_busy=false;Tabs.IsEnabled=true;}}
    public async Task RefreshAsync()
    {
        _snapshot=await _api.GetAsync<MasterSnapshot>("/api/master/context");var w=_snapshot.Workspace;WorkspaceText.Text=$"{(w.Mode=="Business"?"正式资料工作区":"演示工作区")} · {w.EnterpriseName} · {w.WarehouseName} · 平台尚未连接";EnterpriseBox.Text=w.EnterpriseName;WarehouseBox.Text=w.WarehouseName;
        ShopsGrid.ItemsSource=w.Shops;SkusGrid.ItemsSource=_snapshot.Skus;OpeningsGrid.ItemsSource=await _api.GetAsync<List<OpeningDocument>>("/api/master/openings");_shop=null;_sku=null;_policy=await _api.GetAsync<OpeningPolicy>("/api/master/opening-policy");SeparateApproval.IsChecked=_policy.RequireDifferentApprover;PolicyChangesGrid.ItemsSource=await _api.GetAsync<List<OpeningPolicyChange>>("/api/master/policy-changes");
        ApplyPermissions(this);MappingRows.Clear();foreach(var m in _snapshot.Mappings){var shop=w.Shops.Single(s=>s.Id==m.ShopId);var sku=_snapshot.Skus.Single(s=>s.Id==m.InternalSkuId);MappingRows.Add(new(){PlatformName=m.Platform.ToString(),ShopExternalId=shop.ExternalId,Product=m.PlatformProductId,Variant=m.PlatformSkuId,SkuCode=sku.Code,Multiplier=m.UnitMultiplier,Enabled=m.Enabled,ExpectedVersion=m.Version});}_preview="";
    }
    private void ApplyPermissions(DependencyObject parent){foreach(var child in LogicalTreeHelper.GetChildren(parent).OfType<DependencyObject>()){if(child is Button b&&b.Content is string title){var permission=title switch{"保存企业与仓库" or "新建店铺" or "保存店铺" or "新建商品" or "保存商品" or "提交本批映射"=>"security.manage","保存期初待审核单" or "保存所选草稿修改" or "作废所选草稿"=>"opening.write","审核所选期初单并入账"=>"opening.approve","申请变更审核策略" or "批准所选策略申请"=>"opening.policy",_=>""};if(permission.Length>0)b.IsEnabled=_api.Allows(permission);}ApplyPermissions(child);}}
    private async Task<MasterResult> Post(string url,object body){if(_api.PendingCount>0)throw new BusinessRuleException("先核清已有未确认请求。");var r=await _api.PostCommandAsync<MasterResult>(url,body);StatusText.Text=r.Message;return r;}
    public async Task SaveWorkspaceAsync(){await Post("/api/master/workspace",new{expectedVersion=_snapshot!.Workspace.Version,enterpriseName=EnterpriseBox.Text,warehouseName=WarehouseBox.Text,reason=ReasonBox.Text});await RefreshAsync();}
    public async Task SaveShopAsync(){var r=await Post("/api/master/shops",new{id=_shop?.Id,expectedVersion=_shop?.Version??0,platform=(Platform)ShopPlatform.SelectedItem,externalId=ShopExternal.Text,name=ShopName.Text,enabled=ShopEnabled.IsChecked==true,reason=ReasonBox.Text});await RefreshAsync();ShopsGrid.SelectedItem=_snapshot!.Workspace.Shops.Single(x=>x.Id==r.Id);}
    private async Task ResolveAsync(IEnumerable<string>? codes=null,IEnumerable<string>? ids=null,List<SkuMapping>? keys=null){var r=await _api.PostAsync<MasterLookup>("/api/master/lookup",new MasterLookupRequest(codes?.Distinct().ToList()??[],ids?.Distinct().ToList()??[],keys??[]));foreach(var sku in r.Skus){_snapshot!.Skus.RemoveAll(s=>s.Id==sku.Id);_snapshot.Skus.Add(sku);}foreach(var m in r.Mappings){_snapshot!.Mappings.RemoveAll(x=>WorkspaceStoreKey(x,m));_snapshot.Mappings.Add(m);}}
    private static bool WorkspaceStoreKey(SkuMapping a,SkuMapping b)=>a.Platform==b.Platform&&a.ShopId==b.ShopId&&a.PlatformProductId==b.PlatformProductId&&a.PlatformSkuId==b.PlatformSkuId;
    public async Task SaveSkuAsync()
    {
        await ResolveAsync(codes:ComponentsBox.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(l=>l.Split('=')[0].Trim()));var components=new List<SkuComponent>();foreach(var line in ComponentsBox.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)){var parts=line.Split('=');if(parts.Length!=2)throw new BusinessRuleException("组件格式应为 SKU编码=数量。");var child=_snapshot!.Skus.SingleOrDefault(s=>s.Code==parts[0].Trim())??throw new BusinessRuleException("组件 SKU 不存在。");components.Add(new(child.Id,decimal.Parse(parts[1],CultureInfo.InvariantCulture)));}
        var r=await Post("/api/master/skus",new{id=_sku?.Id,expectedVersion=_sku?.Version??0,code=SkuCode.Text,name=SkuName.Text,unit=SkuUnit.Text,enabled=SkuEnabled.IsChecked==true,components,reason=ReasonBox.Text});await RefreshAsync();await ResolveAsync(ids:[r.Id]);SkusGrid.ItemsSource=_snapshot!.Skus.ToList();SkusGrid.SelectedItem=_snapshot.Skus.Single(s=>s.Id==r.Id);
    }
    public void NewShop(){_shop=null;ShopsGrid.SelectedItem=null;ShopPlatform.IsEnabled=true;ShopExternal.IsReadOnly=false;ShopExternal.Clear();ShopName.Clear();ShopEnabled.IsChecked=true;}
    public void NewSku(){_sku=null;SkusGrid.SelectedItem=null;SkuCode.IsReadOnly=false;SkuCode.Clear();SkuName.Clear();SkuUnit.Text="件";SkuEnabled.IsChecked=true;ComponentsBox.Clear();}
    private void Shop_Selected(object sender,SelectionChangedEventArgs e){if(ShopsGrid.SelectedItem is not ShopProfile s)return;_shop=s;ShopPlatform.SelectedItem=s.Platform;ShopPlatform.IsEnabled=false;ShopExternal.Text=s.ExternalId;ShopExternal.IsReadOnly=true;ShopName.Text=s.Name;ShopEnabled.IsChecked=s.Enabled;}
    private void Sku_Selected(object sender,SelectionChangedEventArgs e){if(SkusGrid.SelectedItem is not SkuProfile s)return;_sku=s;SkuCode.Text=s.Code;SkuCode.IsReadOnly=true;SkuName.Text=s.Name;SkuUnit.Text=s.Unit;SkuEnabled.IsChecked=s.Enabled;ComponentsBox.Text=string.Join("\n",s.Components.Select(c=>$"{_snapshot!.Skus.Single(x=>x.Id==c.SkuId).Code}={c.Quantity.ToString(CultureInfo.InvariantCulture)}"));}
    private static Platform ParsePlatform(string name)=>name switch{"淘宝"=>Platform.Taobao,"拼多多"=>Platform.Pinduoduo,"京东"=>Platform.Jd,"抖店"=>Platform.Douyin,_=>Enum.Parse<Platform>(name,true)};
    private List<MappingUpdate> Rows()
    {
        if(!MappingsGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!MappingsGrid.CommitEdit(DataGridEditingUnit.Row,true))throw new BusinessRuleException("映射表存在无效输入。");
        return MappingRows.Select(row=>{var platform=ParsePlatform(row.PlatformName);var shop=_snapshot!.Workspace.Shops.SingleOrDefault(s=>s.Platform==platform&&s.ExternalId==row.ShopExternalId)??throw new BusinessRuleException("店铺标识未登记。");var sku=_snapshot.Skus.SingleOrDefault(s=>s.Code==row.SkuCode)??throw new BusinessRuleException("内部 SKU 编码不存在。");return new MappingUpdate(new(_snapshot.Workspace.TenantId,platform,shop.Id,row.Product,row.Variant,sku.Id,row.Multiplier,row.ExpectedVersion,row.Enabled),row.ExpectedVersion);}).ToList();
    }
    public async Task PreviewMappingsAsync(){await ResolveAsync(codes:MappingRows.Select(r=>r.SkuCode));var p=await _api.PostAsync<MasterPreview>("/api/master/mappings/preview",new MappingPreviewRequest(Rows()));_preview=p.Valid?p.Hash:"";MappingPreviewText.Text=p.Valid?$"校验通过，共 {p.Rows} 行。修改内容后须重新预览；提交会再次核对版本。":string.Join("\n",p.Errors);}
    public async Task SaveMappingsAsync(){if(_preview.Length==0)throw new BusinessRuleException("请先成功预览本批映射。");await Post("/api/master/mappings",new{rows=Rows(),previewHash=_preview,reason=ReasonBox.Text});await RefreshAsync();}
    public void ImportMappings(string text)
    {
        if(text.Length>120000)throw new BusinessRuleException("映射文件过大，请分批导入。");using var parser=new TextFieldParser(new StringReader(text)){TextFieldType=FieldType.Delimited,HasFieldsEnclosedInQuotes=true};parser.SetDelimiters(",");var header=parser.ReadFields();if(header is null||!header.SequenceEqual(new[]{"平台","店铺标识","平台商品ID","平台SKU","内部SKU编码","倍率","启用"}))throw new BusinessRuleException("CSV表头与界面说明不符。");
        var parsed=new List<MappingDraft>();while(!parser.EndOfData){var f=parser.ReadFields()!;if(f.Length!=7||parsed.Count>=200)throw new BusinessRuleException("每行须7列，每批最多200条。");var platform=ParsePlatform(f[0]);var shop=_snapshot!.Workspace.Shops.SingleOrDefault(s=>s.Platform==platform&&s.ExternalId==f[1]);var old=_snapshot.Mappings.SingleOrDefault(m=>m.Platform==platform&&m.ShopId==shop?.Id&&m.PlatformProductId==f[2]&&m.PlatformSkuId==f[3]);parsed.Add(new(){PlatformName=platform.ToString(),ShopExternalId=f[1],Product=f[2],Variant=f[3],SkuCode=f[4],Multiplier=decimal.Parse(f[5],CultureInfo.InvariantCulture),Enabled=bool.Parse(f[6]),ExpectedVersion=old?.Version??0});}
        ApplyPermissions(this);MappingRows.Clear();foreach(var row in parsed)MappingRows.Add(row);_preview="";MappingPreviewText.Text="文件已载入编辑表，尚未保存。请先校验预览。";
    }
    private async Task<List<OpeningLine>> OpeningLinesAsync()
    {
        await ResolveAsync(codes:OpeningLinesBox.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(l=>l.Split(',')[0].Trim()));var balances=await _api.GetAsync<List<InventoryRow>>("/api/inventory");var lines=new List<OpeningLine>();foreach(var text in OpeningLinesBox.Text.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)){var f=text.Split(',');if(f.Length!=2)throw new BusinessRuleException("明细格式应为 SKU编码,数量。");var sku=_snapshot!.Skus.SingleOrDefault(s=>s.Code==f[0].Trim())??throw new BusinessRuleException("SKU不存在。");var stock=balances.SingleOrDefault(s=>s.SkuId==sku.Id)??throw new BusinessRuleException("组合商品不能直接录入库存。");lines.Add(new(sku.Id,decimal.Parse(f[1],CultureInfo.InvariantCulture),sku.Version,stock.Version));}return lines;
    }
    public async Task CreateOpeningAsync(){var r=await Post("/api/master/openings",new{number=OpeningNumber.Text,lines=await OpeningLinesAsync(),reason=ReasonBox.Text});await RefreshAsync();OpeningsGrid.SelectedItem=OpeningsGrid.Items.Cast<OpeningDocument>().FirstOrDefault(x=>x.Id==r.Id);}
    public async Task EditOpeningAsync(){var doc=OpeningsGrid.SelectedItem as OpeningDocument??throw new BusinessRuleException("先选择待审草稿。");await Post($"/api/master/openings/{doc.Id}/edit",new{expectedVersion=doc.Version,lines=await OpeningLinesAsync(),reason=ReasonBox.Text});await RefreshAsync();}
    public async Task VoidOpeningAsync(){var doc=OpeningsGrid.SelectedItem as OpeningDocument??throw new BusinessRuleException("先选择待审草稿。");await Post($"/api/master/openings/{doc.Id}/void",new{expectedVersion=doc.Version,reason=ReasonBox.Text});await RefreshAsync();}
    private async void EditOpening_Click(object sender,RoutedEventArgs e)=>await Run(EditOpeningAsync);
    private async void VoidOpening_Click(object sender,RoutedEventArgs e)=>await Run(VoidOpeningAsync);
    private async void ApprovePolicy_Click(object sender,RoutedEventArgs e)=>await Run(async()=>{if(PolicyChangesGrid.SelectedItem is not OpeningPolicyChange change)throw new BusinessRuleException("请先选中策略申请。");if(change.RequestedBy==_api.CurrentAccount?.Id)throw new BusinessRuleException("申请人不能批准自己的策略变更，请由另一账号操作。");await Post($"/api/master/policy-changes/{change.Id}/approve",new{expectedVersion=change.Version,reason=ReasonBox.Text});await RefreshAsync();});
    private async void SavePolicy_Click(object sender,RoutedEventArgs e)=>await Run(async()=>{await Post("/api/master/opening-policy",new{expectedVersion=_policy.Version,requireDifferentApprover=SeparateApproval.IsChecked==true,reason=ReasonBox.Text});await RefreshAsync();});
    private async void Browse_Click(object sender,RoutedEventArgs e)=>await Run(async()=>{var w=new MasterBrowseWindow(_api,LoadRecord){Owner=this};await w.RefreshAsync();w.ShowDialog();});
    internal async Task LoadRecord(object row){await RefreshAsync();await ResolveAsync(ids:row switch{SkuProfile s=>new[]{s.Id},OpeningDocument d=>d.Lines.Select(l=>l.SkuId),SkuMapping m=>new[]{m.InternalSkuId},_=>Array.Empty<string>()});SkusGrid.ItemsSource=_snapshot!.Skus.ToList();switch(row){case SkuProfile sku:Tabs.SelectedIndex=1;SkusGrid.SelectedItem=_snapshot!.Skus.SingleOrDefault(x=>x.Id==sku.Id)??throw new BusinessRuleException("商品已不存在，请刷新列表。");break;case OpeningDocument doc:doc=await _api.GetAsync<OpeningDocument>("/api/master/openings/"+Uri.EscapeDataString(doc.Id));await ResolveAsync(ids:doc.Lines.Select(l=>l.SkuId));Tabs.SelectedIndex=3;var all=OpeningsGrid.Items.Cast<OpeningDocument>().Where(x=>x.Id!=doc.Id).Prepend(doc).ToList();OpeningsGrid.ItemsSource=all;OpeningsGrid.SelectedItem=doc;break;case SkuMapping m:Tabs.SelectedIndex=2;MappingRows.Clear();MappingRows.Add(new(){PlatformName=m.Platform.ToString(),ShopExternalId=_snapshot!.Workspace.Shops.Single(x=>x.Id==m.ShopId).ExternalId,Product=m.PlatformProductId,Variant=m.PlatformSkuId,SkuCode=_snapshot.Skus.Single(x=>x.Id==m.InternalSkuId).Code,Multiplier=m.UnitMultiplier,Enabled=m.Enabled,ExpectedVersion=m.Version});_preview="";break;case UnmappedSku u:Tabs.SelectedIndex=2;MappingRows.Clear();var old=_snapshot!.Mappings.SingleOrDefault(m=>m.Platform==u.Platform&&m.ShopId==u.ShopId&&m.PlatformProductId==u.ProductId&&m.PlatformSkuId==u.VariantId);MappingRows.Add(new(){PlatformName=u.Platform.ToString(),ShopExternalId=u.ExternalShopId,Product=u.ProductId,Variant=u.VariantId,ExpectedVersion=old?.Version??0});_preview="";break;}}
    public async Task ApproveOpeningAsync(){if(OpeningsGrid.SelectedItem is not OpeningDocument doc)throw new BusinessRuleException("先选择期初单。");var r=await Post($"/api/master/openings/{doc.Id}/approve",new{expectedVersion=doc.Version,reason=ReasonBox.Text});await RefreshAsync();OpeningsGrid.SelectedItem=OpeningsGrid.Items.Cast<OpeningDocument>().FirstOrDefault(x=>x.Id==r.Id);}
    private async void Opening_Selected(object sender,SelectionChangedEventArgs e){if(OpeningsGrid.SelectedItem is not OpeningDocument doc)return;try{if(doc.Lines.Any(l=>!_snapshot!.Skus.Any(s=>s.Id==l.SkuId))){OpeningLinesBox.IsEnabled=false;await ResolveAsync(ids:doc.Lines.Select(l=>l.SkuId));}if(!ReferenceEquals(OpeningsGrid.SelectedItem,doc))return;OpeningNumber.Text=doc.Number;OpeningLinesBox.Text=string.Join("\n",doc.Lines.Select(l=>$"{_snapshot!.Skus.Single(s=>s.Id==l.SkuId).Code},{l.Quantity.ToString(CultureInfo.InvariantCulture)}"));OpeningDetail.Text=string.Join("\n",doc.Lines.Select(l=>$"{_snapshot!.Skus.Single(s=>s.Id==l.SkuId).Code}：{l.Quantity}"));}catch(Exception ex){StatusText.Text="载入期初明细失败："+ex.Message;}finally{OpeningLinesBox.IsEnabled=true;}}
    public async Task ShowHistoryAsync(string entity){HistoryTitle.Text="资料："+entity+" · 最近100条变更";HistoryGrid.ItemsSource=await _api.GetAsync<List<MasterHistory>>("/api/master/history?entity="+Uri.EscapeDataString(entity));Tabs.SelectedIndex=4;}
    private async void History_Click(object sender,RoutedEventArgs e)=>await Run(()=>ShowHistoryAsync(Tabs.SelectedIndex switch{0=>_shop?.Id??"workspace",1=>_sku?.Id??"workspace",2=>"mappings",3=>(OpeningsGrid.SelectedItem as OpeningDocument)?.Id??"workspace",_=>"workspace"}));
    private async void Refresh_Click(object sender,RoutedEventArgs e)=>await Run(RefreshAsync);
    private async void SaveWorkspace_Click(object sender,RoutedEventArgs e)=>await Run(SaveWorkspaceAsync);
    private async void SaveShop_Click(object sender,RoutedEventArgs e)=>await Run(SaveShopAsync);
    private async void SaveSku_Click(object sender,RoutedEventArgs e)=>await Run(SaveSkuAsync);
    private void NewShop_Click(object sender,RoutedEventArgs e)=>NewShop();private void NewSku_Click(object sender,RoutedEventArgs e)=>NewSku();
    private async void PreviewMappings_Click(object sender,RoutedEventArgs e)=>await Run(PreviewMappingsAsync);private async void SaveMappings_Click(object sender,RoutedEventArgs e)=>await Run(SaveMappingsAsync);
    private void ClearMappings_Click(object sender,RoutedEventArgs e){MappingRows.Clear();_preview="";}
    private async Task CaptureMappingVersionsAsync(){var keys=MappingRows.Select(row=>{var platform=ParsePlatform(row.PlatformName);var shop=_snapshot!.Workspace.Shops.SingleOrDefault(s=>s.Platform==platform&&s.ExternalId==row.ShopExternalId)??throw new BusinessRuleException("店铺标识未登记。");return new SkuMapping(_snapshot.Workspace.TenantId,platform,shop.Id,row.Product,row.Variant,"",1,0);}).ToList();await ResolveAsync(keys:keys);foreach(var row in MappingRows){var p=ParsePlatform(row.PlatformName);var shop=_snapshot!.Workspace.Shops.Single(s=>s.Platform==p&&s.ExternalId==row.ShopExternalId);row.ExpectedVersion=_snapshot.Mappings.SingleOrDefault(m=>m.Platform==p&&m.ShopId==shop.Id&&m.PlatformProductId==row.Product&&m.PlatformSkuId==row.Variant)?.Version??0;}MappingsGrid.Items.Refresh();}
    private async void Unmapped_Click(object sender,RoutedEventArgs e)=>await Run(async()=>{var page=await _api.GetAsync<MasterPage<UnmappedSku>>("/api/master/unmapped/page?size=200");MappingRows.Clear();foreach(var row in page.Items)MappingRows.Add(new(){PlatformName=row.Platform.ToString(),ShopExternalId=row.ExternalShopId,Product=row.ProductId,Variant=row.VariantId});await CaptureMappingVersionsAsync();_preview="";MappingPreviewText.Text=$"待处理共{page.Total}项，本批最多200项。更多记录请使用分页检索。";});
    private async void ImportMapping_Click(object sender,RoutedEventArgs e)=>await Run(async()=>{var dlg=new Microsoft.Win32.OpenFileDialog{Filter="映射CSV|*.csv"};if(dlg.ShowDialog()==true){if(new FileInfo(dlg.FileName).Length>360000)throw new BusinessRuleException("文件过大。");ImportMappings(File.ReadAllText(dlg.FileName));await CaptureMappingVersionsAsync();}});
    private async void CreateOpening_Click(object sender,RoutedEventArgs e)=>await Run(CreateOpeningAsync);private async void ApproveOpening_Click(object sender,RoutedEventArgs e)=>await Run(ApproveOpeningAsync);
